from dataclasses import dataclass
from adaptix import Retort, name_mapping, DebugTrail, NameStyle, ExtraForbid
from adaptix._internal.morphing.facade.func import generate_json_schema
from adaptix._internal.definitions import Direction
from adaptix.struct_trail import get_trail
@dataclass
class M:
 first_name: int
 other: int = 2
for mode in DebugTrail:
 r=Retort(debug_trail=mode, recipe=[name_mapping(M, aliases={'first_name':['old','older']}, alias_style=NameStyle.CAMEL, extra_in=ExtraForbid())])
 for k in ('first_name','old','older','firstName'):
  assert r.load({k:1},M)==M(1)
 try: r.load({'old':1,'older':2},M)
 except Exception: pass
 else: raise AssertionError('conflict accepted')
 if mode == DebugTrail.FIRST:
  try: r.load({'old':'bad'},M)
  except Exception as e: assert list(get_trail(e)) == ['old']
  else: raise AssertionError('invalid input accepted')
s=generate_json_schema(r,M,direction=Direction.INPUT)
print('Alias behavior and schema:', s)
PY
